parameters.query:
INSERT INTO public.leads (full_name, email, phone, company, service_interest, monthly_budget, project_description, metadata)
VALUES (
  $1, $2, $3, $4, $5, $6, $7, $8::jsonb
)
RETURNING id, created_at;

parameters.responseBody:
={
  "success": true,
  "message": "Lead procesado correctamente por n8n y almacenado en Supabase",
  "leadId": "{{ $json.id }}",
  "timestamp": "{{ $json.created_at }}"
}

